use std::io

struct Tree {
    key: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn find(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.key[cur as usize]
            if x == k { return true }
            if x < k { cur = self.left[cur as usize] } else { cur = self.right[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.find(x) { return false }
        let id = self.key.len() as int
        self.key.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.key[cur as usize]
            if x < k {
                let l = self.left[cur as usize]
                if l < 0 {
                    self.left[cur as usize] = id
                    return true
                }
                cur = l
            } else {
                let r = self.right[cur as usize]
                if r < 0 {
                    self.right[cur as usize] = id
                    return true
                }
                cur = r
            }
        }
        true
    }

    fn remove(self, node: int, x: int) -> int {
        if node < 0 { return -1 }
        let n = node as usize
        let k = self.key[n]
        if x < k {
            self.left[n] = self.remove(self.left[n], x)
            return node
        }
        if x > k {
            self.right[n] = self.remove(self.right[n], x)
            return node
        }
        if self.left[n] < 0 { return self.right[n] }
        if self.right[n] < 0 { return self.left[n] }
        let mut s = self.right[n]
        while self.left[s as usize] >= 0 { s = self.left[s as usize] }
        let sk = self.key[s as usize]
        self.key[n] = sk
        self.right[n] = self.remove(self.right[n], sk)
        node
    }

    fn height(self, node: int) -> int {
        if node < 0 { return 0 }
        let a = self.height(self.left[node as usize])
        let b = self.height(self.right[node as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, node: int, out: Vec<int>) -> Vec<int> {
        let mut res = out
        if node < 0 { return res }
        res = self.walk(self.left[node as usize], res)
        res.push(self.key[node as usize])
        res = self.walk(self.right[node as usize], res)
        res
    }
}

fn main() {
    let input = io::read_to_string(io::stdin()) ?? ""
    let mut t = Tree { key: [], left: [], right: [], root: -1 }
    for line in input.split("\n") {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse() ?? 0
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse() ?? 0
            if t.find(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse() ?? 0
            if t.find(x) {
                t.root = t.remove(t.root, x)
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let v = t.walk(t.root, [])
            if v.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut first = true
                for k in v {
                    if !first { s = s + " " }
                    s = s + "${k}"
                    first = false
                }
                println(s)
            }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                while t.left[c as usize] >= 0 { c = t.left[c as usize] }
                println("${t.key[c as usize]}")
            }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                while t.right[c as usize] >= 0 { c = t.right[c as usize] }
                println("${t.key[c as usize]}")
            }
        }
    }
}

